probe:
package CorsairProbe;
use strict;
use warnings;
use lib '/work/lib';
use Net::Netmask;

our $CONTROL_PAYLOAD = '192.0.1.2/32';
our $EXPLOIT_PAYLOAD = '192.0.01.2/32';

sub run_target {
    my ($payload) = @_;
    my ($address) = split m{/}, $payload, 2;
    my $network;
    {
        local $@;
        $network = eval { Net::Netmask->new2($payload) };
        die $@ if $@;
    }
    return 1 unless defined $network;
    return $network->base() eq $address ? 1 : 0;
}

1;
